            rule_section(:variants, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0438 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438",
              "\u0421 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044F\u043C\u0438: \u043F\u044F\u0442\u044C \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445, \u043A\u0430\u0440\u0435, \u0444\u0443\u043B-\u0445\u0430\u0443\u0441, \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C, \u0442\u0440\u043E\u0439\u043A\u0430, \u0434\u0432\u0435 \u043F\u0430\u0440\u044B, \u043F\u0430\u0440\u0430, \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u043E\u0441\u0442\u044C. \u041F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u2014 1\u20135 \u0438 2\u20136; 2\u20136 \u0432\u044B\u0448\u0435. \u0412 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u0431\u0435\u0437 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0435\u0439 \u044D\u0442\u043E \u043F\u0440\u043E\u0441\u0442\u043E \u0441\u0442\u0430\u0440\u0448\u0438\u0435 \u043A\u043E\u0441\u0442\u0438. \u041E\u0431\u044B\u0447\u043D\u043E \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u0433\u0440\u0430\u043D\u044C \u2014 \u0448\u0435\u0441\u0442\u044C; \u0432 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u0441 \u0442\u0443\u0437\u0430\u043C\u0438 \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0432\u044B\u0448\u0435 \u0448\u0435\u0441\u0442\u0451\u0440\u043E\u043A, \u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F. \u041F\u0440\u0438 \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0439 \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u044E\u0449\u0438\u0435\u0441\u044F \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F, \u0437\u0430\u0442\u0435\u043C \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u041C\u0430\u0441\u0442\u0435\u0439 \u0438 \u0444\u043B\u0435\u0448\u0435\u0439 \u043D\u0435\u0442."),
            rule_section(:turns, "\u0411\u0440\u043E\u0441\u043A\u0438 \u0438 \u0440\u0430\u0443\u043D\u0434\u044B",
              "\u0412\u044B\u0431\u0435\u0440\u0438 \u0434\u0432\u0430 \u0438\u043B\u0438 \u0442\u0440\u0438 \u0431\u0440\u043E\u0441\u043A\u0430 \u043D\u0430 \u0445\u043E\u0434 \u0438 1\u201320 \u0440\u0430\u0443\u043D\u0434\u043E\u0432. \u0415\u0441\u043B\u0438 \u0432\u043A\u043B\u044E\u0447\u0451\u043D \u043B\u0438\u043C\u0438\u0442 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u0431\u0440\u043E\u0441\u043A\u043E\u0432, \u0447\u0435\u043C \u043E\u043D \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043B \u0432 \u0440\u0430\u0443\u043D\u0434\u0435. \u041D\u0430\u0447\u0438\u043D\u0430\u044E\u0449\u0435\u0435 \u043C\u0435\u0441\u0442\u043E \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A\u0430\u0436\u0434\u044B\u0439 \u0440\u0430\u0443\u043D\u0434. \u041A\u043E\u0441\u0442\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044B; \u043A\u0430\u0436\u0434\u044B\u0439 \u0431\u0440\u043E\u0441\u043E\u043A \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E\u0441\u0442\u044C \u0441\u0435\u0440\u0432\u0435\u0440\u0430. \u041F\u0435\u0440\u0435\u0434 \u043D\u043E\u0432\u044B\u043C \u0431\u0440\u043E\u0441\u043A\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043E\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438."),
            rule_section(:betting, "\u0421\u0442\u0430\u0432\u043A\u0438 \u0444\u0438\u0448\u043A\u0430\u043C\u0438",
              "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043E\u0447\u043A\u0438 \u0438\u043B\u0438 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0435 \u0444\u0438\u0448\u043A\u0438. \u041A\u0430\u0436\u0434\u044B\u0439 \u043F\u043B\u0430\u0442\u0438\u0442 \u0430\u043D\u0442\u0435 \u043B\u0438\u0431\u043E \u0432\u0435\u0441\u044C \u043E\u0441\u0442\u0430\u0442\u043E\u043A \u043F\u0440\u0438 \u043D\u0435\u0445\u0432\u0430\u0442\u043A\u0435. \u0422\u043E\u0440\u0433\u043E\u0432\u043B\u044F \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u0434\u043E \u0431\u0440\u043E\u0441\u043A\u043E\u0432 \u0438 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0439. \u041C\u043E\u0436\u043D\u043E \u0447\u0435\u043A\u0430\u0442\u044C, \u0443\u0440\u0430\u0432\u043D\u044F\u0442\u044C, \u043F\u043E\u0432\u044B\u0441\u0438\u0442\u044C \u0441\u0432\u043E\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439, \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0438\u043B\u0438 \u043F\u043E\u0439\u0442\u0438 all-in. \u0421\u0431\u0440\u043E\u0441\u0438\u0432\u0448\u0438\u0439 \u043D\u0435 \u0431\u0440\u043E\u0441\u0430\u0435\u0442, all-in \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0431\u0440\u043E\u0441\u043A\u0438. \u0412\u0437\u043D\u043E\u0441\u044B \u0441\u043E\u0437\u0434\u0430\u044E\u0442 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u0438 \u043F\u043E\u0431\u043E\u0447\u043D\u044B\u0435 \u0431\u0430\u043D\u043A\u0438; \u043B\u0443\u0447\u0448\u0438\u0439 \u0434\u043E\u043F\u0443\u0449\u0435\u043D\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043B\u043E\u0439, \u0440\u0430\u0432\u043D\u044B\u0435 \u0434\u0435\u043B\u044F\u0442 \u043F\u043E \u043C\u0435\u0441\u0442\u0430\u043C. \u041D\u0435\u043F\u043E\u043A\u0440\u044B\u0442\u044B\u0435 \u0447\u0430\u0441\u0442\u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F. \u0415\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0439\u0441\u044F \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0431\u0435\u0437 \u0431\u0440\u043E\u0441\u043A\u043E\u0432. \u0418\u0433\u0440\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E \u043B\u0438\u043C\u0438\u0442\u0443 \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u0438\u043B\u0438 \u0441 \u043E\u0434\u043D\u0438\u043C \u043F\u043B\u0430\u0442\u0451\u0436\u0435\u0441\u043F\u043E\u0441\u043E\u0431\u043D\u044B\u043C \u0438\u0433\u0440\u043E\u043A\u043E\u043C. C \u0447\u0435\u043A/\u043A\u043E\u043B\u043B, F \u0441\u0431\u0440\u043E\u0441, A all-in, B \u0438\u043B\u0438 R \u0432\u0432\u043E\u0434 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u044F, S \u0431\u0430\u043B\u0430\u043D\u0441."),
            rule_section(:controls, "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435",
              "Enter \u0431\u0440\u043E\u0441\u0430\u0435\u0442 \u043A\u043E\u0441\u0442\u0438. \u041F\u043E\u0441\u043B\u0435 \u0431\u0440\u043E\u0441\u043A\u0430 1\u20136 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0441 \u044D\u0442\u043E\u0439 \u0433\u0440\u0430\u043D\u044C\u044E \u0434\u043B\u044F \u043F\u0435\u0440\u0435\u0431\u0440\u043E\u0441\u0430; Shift+1\u20136 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u0435\u0451. Enter \u043F\u0435\u0440\u0435\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438; \u0431\u0435\u0437 \u0432\u044B\u0431\u043E\u0440\u0430 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438. K \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u044E \u0441\u0440\u0430\u0437\u0443. \u041F\u0440\u043E\u0431\u0435\u043B \u0447\u0438\u0442\u0430\u0435\u0442 \u043A\u043E\u0441\u0442\u0438 \u0438 \u0432\u044B\u0431\u043E\u0440, S \u2014 \u043E\u0447\u043A\u0438. F1 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u043A\u043E\u043C\u0430\u043D\u0434\u044B, Ctrl+F1 \u2014 \u043F\u0440\u0430\u0432\u0438\u043B\u0430. \u0427\u0430\u0442, \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0438 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442 \u043E\u0431\u0449\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438.")
          ]
        end
